<template>
  <div class="project-camps"><header class="pcb-head"><h2>参加的营期</h2><DewButton v-if="project.can_manage && project.can_write" size="sm" @click="open()">申请参加营期</DewButton></header><p v-if="error" role="alert">{{ error }}</p><DewSkeleton v-else-if="loading" variant="rect" width="100%" height="150" /><template v-else><p v-if="!rows.length" class="pcb-muted">项目尚未关联营期，长期项目工作不受影响。</p><article v-for="row in rows" :key="row.id" class="pcb-row"><h3>{{ row.camp_name }} <DewTag size="sm">{{ states[row.status] }}</DewTag></h3><p class="pcb-muted">{{ row.participants.map(p=>p.name+(p.role==='leader'?'（本期负责人）':'')).join('、') || '等待名单确认' }}</p><p v-if="row.change_pending" class="pcb-muted">有本期名单变更待确认。</p><DewButton v-if="row.status!=='requested' && row.status!=='rejected'" size="sm" type="ghost" @click="$emit('open-binding',row)">查看本期工作</DewButton><DewButton v-if="row.status==='active' && project.can_manage && project.can_write" size="sm" type="ghost" @click="open(row)">申请调整本期名单</DewButton></article></template><DewDialog v-model="dialog" :title="selected ? '申请调整本期名单' : '申请参加营期'" width="620px"><div class="pcb-form"><label v-if="!selected">营期<DewSelect v-model="campId" :options="available.map(c=>({value:c.id,label:c.name}))" placeholder="选择营期" /></label><p>选择本期参加人员，长期团队名单保持独立。</p><label v-for="member in members" :key="member.user_id" class="pcb-check"><input v-model="picked" type="checkbox" :value="member.user_id">{{ member.name }}{{ member.role==='leader'?' · 项目负责人':'' }}</label><label>申请原因<DewInput v-model="reason" placeholder="说明参营目标或名单变更" /></label></div><template #footer><DewButton :loading="busy" :disabled="(!selected&&!campId)||!picked.length||!reason.trim()" @click="submit">提交申请</DewButton></template></DewDialog></div>
</template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue'
import {DewButton,DewTag,DewSelect,DewInput,DewDialog,DewSkeleton} from '@bme/dew-ui'
import {ElMessage} from 'element-plus'
import {projectService,mutation} from './service'
const props=defineProps({project:Object}),emit=defineEmits(['changed','open-binding'])
const rows=ref([]),available=ref([]),members=ref([]),picked=ref([]),campId=ref(null),reason=ref(''),selected=ref(null),dialog=ref(false),busy=ref(false),loading=ref(true),error=ref(''),context=ref(null)
const states={requested:'待审批',active:'参营中',ended:'本期已结束',rejected:'未通过'}
let sequence=0
async function load(){const seq=++sequence;loading.value=true;error.value='';try{const d=await projectService.camps(props.project.id);if(seq===sequence)rows.value=d.bindings;context.value=(await projectService.detail(props.project.id)).project}catch(e){if(seq===sequence)error.value=e.response?.data?.message||'营期关联加载失败'}finally{if(seq===sequence)loading.value=false}}
async function open(row){try{const data=await projectService.members(props.project.id);members.value=data.members.filter(m=>m.role);picked.value=row?row.participants.map(m=>m.user_id):members.value.map(m=>m.user_id);selected.value=row||null;campId.value=null;reason.value='';if(!row)available.value=(await projectService.availableCamps()).camps;dialog.value=true}catch(e){ElMessage.error(e.response?.data?.message||'选项加载失败')}}
async function submit(){if(busy.value)return;busy.value=true;try{const data=mutation(context.value||props.project,{user_ids:picked.value,reason:reason.value});if(selected.value)await projectService.requestParticipants(props.project.id,selected.value.id,{...data,expected_binding_version:selected.value.version});else await projectService.requestCamp(props.project.id,{...data,camp_id:campId.value});dialog.value=false;await load();emit('changed');ElMessage.success('申请已提交')}catch(e){ElMessage.error(e.response?.data?.message||'申请失败')}finally{busy.value=false}}
watch(()=>props.project.id,load,{immediate:true});onBeforeUnmount(()=>sequence++)
</script>
<style scoped>.pcb-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.pcb-row{padding:18px 0;border-bottom:1px solid var(--dew-card-flat-border)}.pcb-row h3{font-size:17px}.pcb-muted{color:var(--dew-text-muted);font-size:13px}.pcb-form{display:flex;flex-direction:column;gap:12px}.pcb-form label{display:flex;flex-direction:column;gap:8px}.pcb-form .pcb-check{flex-direction:row;align-items:center}</style>
